  const icon = (name, cls = '') => '<svg class="icon ' + cls + '" viewBox="0 0 24 24" aria-hidden="true">' + (paths[name] || paths.target) + '</svg>';
  const links = [['home', 'Overview', 'home'], ['players', 'Players', 'users'], ['matches', 'Matches', 'matches'], ['leaderboard', 'Leaderboard', 'trophy'], ['rivalries', 'Head-to-head', 'swords'], ['analytics', 'Analytics', 'chart'], ['records', 'Records & awards', 'medal']];
  const colors = ['#a78bfa', '#22d3ee', '#fb923c', '#60a5fa', '#f472b6', '#4ade80', '#facc15', '#c084fc'];
