    return heading('Every match leaves a mark.', 'The complete history of your late-night battles.', windowSelect()) + '<div class="search-filter"><select class="select" id="match-map" aria-label="Filter by map"><option value="">All maps</option>' + [...new Set(data.matches.map(m => m.map))].map(m => '<option' + (matchMap === m ? ' selected' : '') + '>' + esc(m) + '</option>').join('') + '</select><span class="filter-count">' + filtered.length + ' matches · latest workbook entry first</span></div>' + panel('Match history', 'matches', '<div class="match-list">' + ([...filtered].reverse().slice(matchPage * perPage, (matchPage + 1) * perPage).map(m => matchRow(m)).join('') || empty()) + '</div>', pill('IMPORTED HISTORY')) + (filtered.length > perPage ? '<div class="pagination"><button class="btn small" data-action="prev-page"' + (!matchPage ? ' disabled' : '') + '>Previous</button><span>Page ' + (matchPage + 1) + ' of ' + Math.ceil(filtered.length / perPage) + '</span><button class="btn small" data-action="next-page"' + ((matchPage + 1) * perPage >= filtered.length ? ' disabled' : '') + '>Next</button></div>' : '') + '<div style="height:22px"></div>' + notice('The initial workbook has no match dates or complete scores. Match order follows the Database sheet. Missing values stay unavailable.');
